"""Individual sentence review; residual 1941 measures require current-law integration."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
STJ='https://scon.stj.jus.br/SCON/GetInteiroTeorDoAcordao?num_registro=202403533485'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(373,'Dispositivo do regime histórico de interdições provisórias: não usar como autorização atual genérica para antecipar pena.', ['Texto distingue instrução, pronúncia, confirmação e condenação recorrível.', 'Prazo histórico de dois dias não substitui o procedimento da cautelar atual.', 'Comparar cautelares do art. 319 com execução de sanção na LEP.'], 'A permanência no compilado não permite restaurar automaticamente o sistema penal anterior à reforma de 1984.', 'Risco ligado à função pública exige analisar suspensão cautelar pelo art. 319, VI, com requisitos atuais.', 'Sem risco concreto não se antecipa interdição punitiva por simples acusação.', ['Interdição histórica é cautelar moderna automaticamente? Não.', 'Sanção e cautelar têm o mesmo fundamento? Não.'], 'Regime histórico','Texto que exige integração com legislação posterior.',[LEP])
add(374,'A cláusula histórica de ausência de recurso acompanha interdições do regime antigo, não todas as cautelares contemporâneas.', ['Substituição e revogação eram ligadas às fases do art. 373.', 'Controle atual depende da medida efetivamente aplicada e do instrumento cabível.'], 'Não ensinar irrecorribilidade universal de decisão que restringe direitos.', 'Defesa impugna restrição atual pelo meio adequado ao seu fundamento.', 'Não se rejeita toda impugnação apenas citando a redação antiga do art. 374.', ['Todas as cautelares atuais são irrecorríveis por este artigo? Não.', 'Deve identificar o regime jurídico da medida? Sim.'], 'Controle da restrição','Exame da via adequada à decisão, sem generalizar regra histórica.',[LEP])
add(375,'O texto exige fundamentação ao aplicar, substituir ou revogar interdição histórica; decisões atuais também precisam base própria.', ['Motivos concretos devem permitir compreensão e controle.', 'Fundamentar não torna vigente uma sanção provisória de regime superado.'], 'Não basta escrever que a restrição é necessária sem explicar fatos e base legal atual.', 'Juiz explicita risco e pertinência ao decidir cautelar atual.', 'Motivação detalhada não legitima uma modalidade sem fundamento legal aplicável.', ['Motivação substitui base legal? Não.', 'A decisão precisa explicar seus motivos? Sim.'], 'Fundamentação','Razões concretas de fato e de direito da decisão.',[LEP])
add(376,'A cessação prevista refere-se a interdição provisória histórica; estudar efeitos atuais de impronúncia e absolvição conforme a medida.', ['Não transportar o instituto antigo para prisão ou proteção de vítima sem verificar regras próprias.', 'Absolvição: observar também art. 386, parágrafo único.'], 'Medidas protetivas têm disciplina própria; não concluir que toda proteção cessa mecanicamente por esta remissão antiga.', 'Após absolvição, examinam-se as cautelares penais nos termos atuais.', 'Proteção da vítima exige análise do regime específico e do risco, não aplicação indiscriminada do art. 376.', ['O artigo encerra automaticamente qualquer proteção existente? Não.', 'É necessário identificar a natureza da medida? Sim.'], 'Cessação e natureza jurídica','Efeito examinado segundo a medida realmente aplicada.',[LEP])
add(377,'Execução de interdição como sanção exige título e regime atuais, sem perpetuar restrições provisórias antigas.', ['Distinguir conteúdo da condenação, efeitos legais e cautelar.', 'LEP, art. 147, disciplina execução da pena restritiva de direitos após trânsito em julgado.'], 'Apenas existir restrição durante o processo não a transforma em pena definitiva.', 'Condenação definitiva com pena restritiva é executada no regime da LEP.', 'Medida temporária investigativa não vira automaticamente sanção no título executivo.', ['Cautelar vira pena definitiva por si? Não.', 'O título condenatório importa para execução? Sim.'], 'Título executivo penal','Decisão e efeitos legais que delimitam execução.',[LEP])
add(378,'A medida de segurança provisória descrita no sistema antigo não se confunde com internação cautelar atual.', ['Art. 319, VII, prevê hipótese cautelar específica e requisitos próprios.', 'Medida de segurança definitiva exige pressupostos penais e execução adequada.', 'Diagnóstico isolado não prova necessidade de internar.'], 'Não decretar internação punitiva de ofício só pela redação histórica ou por doença mental.', 'Caso com suspeita de inimputabilidade exige perícia e análise do regime adequado.', 'Sem os requisitos da cautelar atual, o texto antigo não fornece atalho para internar.', ['Doença mental autoriza internação automática? Não.', 'Internação cautelar e medida definitiva são idênticas? Não.'], 'Internação cautelar','Providência específica distinta da execução de medida de segurança.',[LEP])
add(379,'A execução definitiva de medida de segurança deve ser integrada à LEP, especialmente guia e controle judicial.', ['Distinguir sentença, trânsito e início regular da execução.', 'LEP, arts. 171 e 172: guia é requisito da execução prevista.'], 'A remissão histórica ao Livro IV não dispensa os requisitos da legislação de execução posterior.', 'Após título definitivo, são observadas guia e providências legais de execução.', 'Não se inicia execução de medida por mera anotação informal de diagnóstico.', ['Guia pode ser ignorada nessa execução? Não.', 'Diagnóstico isolado equivale a título definitivo? Não.'], 'Guia de execução','Documento judicial exigido pelo regime de execução.',[LEP])
add(380,'A perda da fiança ligada à antiga medida provisória não deve ser ensinada como consequência atual automática.', ['Identificar a natureza da restrição e o regime cautelar aplicável.', 'Não confundir fiança, prisão preventiva e internação cautelar.'], 'Texto residual não restaura medida de segurança provisória antiga nem autoriza desfazer toda fiança por diagnóstico.', 'Pedido de internação cautelar é examinado por seus requisitos atuais.', 'Alegar transtorno sem avaliação pertinente não elimina automaticamente fiança já concedida.', ['Diagnóstico desfaz toda fiança automaticamente? Não.', 'É preciso aplicar o regime atual da medida? Sim.'], 'Fiança e cautelares','Institutos distintos, com pressupostos próprios.',[LEP])
add(381,'Sentença identifica partes, resume acusação e defesa, fundamenta, indica normas, decide e contém data e assinatura.', ['Seis elementos do artigo.', 'Dispositivo é a conclusão; fundamentação explica por quê.', 'Impossibilidade de nomes exige identificação suficiente.'], 'Resumo da acusação não substitui exame da defesa nem motivação judicial.', 'Sentença enfrenta tese defensiva relevante e apresenta conclusão identificável.', 'Apenas copiar denúncia e escrever condenado não satisfaz os elementos exigidos.', ['Dispositivo e fundamentação são iguais? Não.', 'Pode haver identificação suficiente sem nome conhecido? Sim.'], 'Dispositivo','Parte conclusiva da sentença.')
add(382,'Partes podem pedir esclarecimento da sentença em dois dias por obscuridade, ambiguidade, contradição ou omissão.', ['Pedido dirigido ao juiz da sentença.', 'Não importar prazo geral de cinco dias do CPC.', 'Omissão é falta de exame de ponto relevante.'], 'Discordância simples não dispensa demonstrar o defeito próprio do pedido.', 'Sentença omite tese decisiva: parte pede integração dentro do prazo penal.', 'Conclusão desfavorável, mas clara e completa, não cria omissão por si.', ['Prazo deste artigo é cinco dias? Não, dois.', 'Omissão pode motivar o pedido? Sim.'], 'Integração da sentença','Correção dos defeitos enumerados no artigo.')
add(383,'Emendatio libelli altera a definição jurídica sem alterar os fatos narrados na acusação.', ['Pode resultar em pena mais grave na hipótese do artigo.', 'Examinar suspensão condicional do processo quando cabível.', 'Se mudar competência, encaminhar ao juízo competente.'], 'Não confundir nova classificação com inclusão de fato ausente da acusação.', 'Fatos de violência já narrados recebem enquadramento jurídico diverso.', 'Violência somente revelada na prova e não narrada exige examinar art. 384, não disfarçar mudança factual.', ['Emendatio permite modificar os fatos acusados? Não.', 'Nova competência pode exigir remessa? Sim.'], 'Emendatio libelli','Correção do enquadramento com a mesma descrição factual.')
add(384,'Mutatio libelli exige aditamento por novo elemento ou circunstância não contido na acusação, com oportunidade de defesa.', ['MP: cinco dias para aditar na hipótese de ação pública.', 'Defesa ouvida em cinco dias; admitido aditamento, continuação a requerimento de parte.', 'Cada parte pode indicar até três testemunhas em cinco dias.', 'Novo interrogatório, debates e julgamento; decisão vinculada ao aditamento.', 'Sem aditamento: remissão ao art. 28 deve ser integrada à redação atual.', 'Não recebido o aditamento, processo prossegue.'], 'Juiz não inclui sozinho o elemento novo e condena sem contraditório.', 'Prova revela circunstância nova: MP adita e defesa recebe prazo e possibilidade de produzir prova.', 'Se muda só a classificação dos mesmos fatos, aplica-se art. 383.', ['Cada parte pode arrolar três testemunhas no aditamento? Sim.', 'Juiz pode substituir o aditamento acusatório sem defesa? Não.'], 'Mutatio libelli','Alteração da imputação factual mediante procedimento próprio.')
add(385,'Na ação pública, pedido de absolvição do MP não impede por si condenação motivada nos limites da acusação e da prova.', ['STJ reafirmou compatibilidade do artigo com sistema acusatório em 2025.', 'Texto admite reconhecimento de agravantes não alegadas.', 'Correlação com acusação e garantias de defesa permanecem.'], 'Poder condenar não significa dever condenar nem autorização para criar fatos acusatórios.', 'MP pede absolvição, mas juiz avalia prova válida e fundamenta conclusão diferente.', 'Insuficiência probatória exige absolvição; a regra não cria prova inexistente.', ['Pedido absolutório sempre vincula juiz na ação pública? Não.', 'Artigo autoriza inventar fato novo? Não.'], 'Independência decisória','Conclusão judicial fundamentada, sujeita a limites processuais.',[STJ])
add(386,'Absolvição deve indicar seu fundamento: inexistência, falta de prova, atipicidade, autoria ou exclusão/isenção e dúvida pertinente.', ['I/II: inexistência provada versus ausência de prova do fato.', 'IV/V: não participação provada versus falta de prova de participação.', 'VI inclui fundada dúvida sobre excludente; VII é prova insuficiente.', 'Dispositivo indica causa; examinar liberdade e cessação cautelar.', 'Medida de segurança somente se juridicamente cabível.'], 'Absolvição não significa em todas as hipóteses prova de que o fato nunca ocorreu; diagnóstico não impõe medida automática.', 'Prova demonstra que acusado estava em outro local: fundamento de não participação provada.', 'Autoria permanece incerta: ausência de prova de participação, sem afirmar certeza positiva de inocorrência.', ['Inexistência provada e falta de prova são iguais? Não.', 'Medida de segurança cabe em toda absolvição? Não.'], 'Fundamento absolutório','Razão jurídica precisa da absolvição.')
add(387,'Condenação fundamenta pena, reparação mínima, cautelares e detração para regime inicial; há remissões antigas que exigem integração.', ['Circunstâncias e pena devem ser individualizadas.', 'Reparação mínima exige observar contraditório e jurisprudência aplicável ao tipo de dano.', 'Prisão ou outra cautelar exige decisão própria fundamentada, sem impedir conhecimento da apelação.', 'Detração do §2º é considerada na definição do regime inicial.', 'Incisos V/VI remetem a institutos antigos; não restaurar interdição provisória punitiva ou publicação como pena antiga.'], 'Não automatizar prisão ao condenar nem reparar sem examinar pedido, dano e regime jurisprudencial pertinente.', 'Juiz justifica pena e avalia tempo cautelar para regime inicial, separando decisão de prisão.', 'Condenação sem risco cautelar não basta, por si, para nova preventiva; reparação requer análise própria.', ['Condenação impõe preventiva automaticamente? Não.', 'Detração do §2º serve para examinar regime inicial? Sim.'], 'Individualização da condenação','Decisões distintas sobre pena, danos e cautelares.',[LEP])
add(388,'Redação sobre sentença datilografada e rubrica expressa formalização e autenticidade, integrada hoje ao processo eletrônico.', ['Não confundir forma histórica com exigência exclusiva de máquina de escrever.', 'Assinatura e integridade seguem também regime eletrônico aplicável.'], 'Não exigir rubricar fisicamente cada página de toda sentença eletrônica sem considerar legislação digital.', 'Documento judicial eletrônico recebe assinatura válida no sistema competente.', 'Texto sem identificação ou assinatura não se torna sentença autêntica por estar em PDF.', ['Datilografia é única forma atual? Não.', 'Autenticidade continua relevante? Sim.'], 'Autenticidade documental','Controle da autoria e integridade do ato judicial.')
add(389,'Publicação judicial da sentença é ato formal nos autos, distinto de notícia de imprensa e de intimação de todos os destinatários.', ['Redação descreve termo e registro históricos.', 'Integrar os meios oficiais do processo eletrônico.', 'Publicação e ciência para prazo podem exigir atos diferentes.'], 'Uma reportagem ou postagem não substitui publicação e intimação processuais exigidas.', 'Sentença é formalizada no processo e depois comunicada conforme regime de cada sujeito.', 'Divulgar resultado em rede social não comprova intimação da defesa.', ['Publicação jornalística substitui intimação? Não.', 'Publicação e intimação são sempre o mesmo ato? Não.'], 'Publicação judicial','Formalização oficial da sentença no processo.')
add(390,'Escrivão deve dar conhecimento da sentença ao MP em três dias após publicação; não é prazo de apelação.', ['Integrar intimação pessoal do MP, art. 370, §4º.', 'Texto contém previsão histórica disciplinar; sanção não dispensa procedimento e garantias atuais.'], 'Não confundir os três dias de comunicação com prazo recursal nem aplicar punição disciplinar automática sem garantias.', 'Secretaria comunica sentença ao MP pelo canal oficial apropriado.', 'Atraso exige apuração pertinente, não suspensão sumária sem defesa.', ['Os três dias são prazo de apelação? Não.', 'A ciência do MP tem regime pessoal? Sim.'], 'Comunicação ao MP','Providência da secretaria distinta de recurso.')
add(391,'Querelante ou assistente recebe intimação pessoal ou por advogado; ausência de ambos na sede pode levar a edital de dez dias.', ['Regra específica desses sujeitos.', 'Não confundir com edital de intimação da sentença ao réu.', 'Certificar as condições da hipótese.'], 'Prazo de dez dias não é regra universal de todo edital penal.', 'Assistente é intimado por seu advogado regularmente localizado.', 'Se ambos não são encontrados na sede, examina-se hipótese de edital deste artigo.', ['Este edital é universal para todo réu? Não.', 'Advogado pode receber ciência do assistente? Sim.'], 'Ciência do assistente','Intimação específica prevista para querelante ou assistente.')
add(392,'Intimação da sentença ao réu varia conforme prisão, defesa constituída e localização, com formalidades de edital.', ['Réu preso: intimação pessoal.', 'Hipóteses de defensor constituído e edital exigem condições e certidão previstas.', 'Edital: noventa dias se pena privativa igual ou superior a um ano; sessenta nos demais casos.', 'Apelação após edital, salvo outra intimação regular durante ele.', 'Defensor nomeado conserva regime pessoal do art. 370, §4º.'], 'Não trocar noventa/sessenta por dez dias nem suprimir defesa técnica sob justificativa de réu não localizado.', 'Réu preso é intimado pessoalmente da sentença.', 'Edital pertinente com pena de um ano usa noventa dias, observadas condições e ciência do defensor.', ['Réu preso recebe pessoalmente? Sim.', 'Pena de exatamente um ano entra nos noventa dias? Sim.'], 'Intimação da sentença','Ciência regular conforme situação do acusado e defesa.')
assert len(rows)==20
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'sentence units reviewed')
